// requireNotVerify refuses an ArgoCD-facing command aimed at a verify
// environment. deploy, diff and sync all assume the environment is reconciled
// by ArgoCD; a verify environment is dry-run against a local cluster by
// `deploy verify` instead, so aiming one of them at it is a category error
// rather than a run that happens to do nothing.
func requireNotVerify(command, env string, cfg gitops.EnvironmentConfig) error {
	if !cfg.Verify {
		return nil
	}
	return fmt.Errorf("%s is a verify environment: `deploy %s` does not apply — nothing is deployed, diffed or synced there. Use `deploy verify` to dry-run its manifests against the local verification cluster", env, command)
}

