arguments.content:
// Package verify runs GitOps manifests against a local verification cluster:
// it manages the k3d cluster and its platform dependencies, and dry-runs a
// rendered overlay against the API server without creating any workload.
//
// The cluster is shared and long-lived — creating one is the expensive part,
// so `up` is run once and the cluster is reused across every verification.
// What a verification run creates is a single namespace, which is deleted
// again on success: one call that takes everything the run owned with it.
package verify

import (
	"context"
	"errors"
	"fmt"
	"io"

	"github.com/integrio-intropy/intropy-cli/internal/command"
)

// DefaultClusterName is the k3d cluster every verification shares.
const DefaultClusterName = "intropy-verify"

// KubeContext is the kubectl context k3d writes for the cluster, which is how
// every call here addresses it without touching the user's current context.
const KubeContext = "k3d-" + DefaultClusterName

// Binaries are what Up and Run shell out to. Checked up front, so a missing
// tool fails before any cluster state is touched rather than halfway through a
// dependency install.
var Binaries = []string{"k3d", "kubectl", "helm"}

// Runner is the seam tests replace. It is the production exec runner by
// default, matching how the deploy package treats git and kustomize.
var Runner command.Runner

func runner() command.Runner {
	if Runner != nil {
		return Runner
	}
	return command.ExecRunner{}
}

// Cluster is the shared local verification cluster.
type Cluster struct {
	// Name is the k3d cluster name, DefaultClusterName unless overridden.
	Name string

	// Stderr receives progress: cluster and dependency work is slow, so the
	// user watches it happen rather than wondering.
	Stderr io.Writer
}

func (c Cluster) name() string {
	if c.Name != "" {
		return c.Name
	}
	return DefaultClusterName
}

func (c Cluster) progress(format string, args ...any) {
	if c.Stderr != nil {
		fmt.Fprintf(c.Stderr, format+"\n", args...)
	}
}

// exists reports whether the cluster is already created. `k3d cluster list`
// prints a header plus one line per cluster, with the name first.
func (c Cluster) exists(ctx context.Context) (bool, error) {
	out, _, err := runner().Run(ctx, "", "k3d", "cluster", "list", "--no-headers")
	if err != nil {
		return false, fmt.Errorf("list k3d clusters: %w", err)
	}
	for line := range splitLines(out) {
		if firstField(line) == c.name() {
			return true, nil
		}
	}
	return false, nil
}

// Up creates the cluster if absent and installs the platform dependencies.
// Both halves are idempotent, so running it on a warm cluster is a cheap no-op
// — which is the common case, and the reason verification stays fast.
func (c Cluster) Up(ctx context.Context) error {
	found, err := c.exists(ctx)
	if err != nil {
		return err
	}
	if found {
		c.progress("cluster %s already exists", c.name())
	} else {
		c.progress("creating k3s cluster %s", c.name())
		// No traefik: the cluster's ingress is kgateway, and the fewer
		// controllers starting up the faster the API answers.
		if _, _, err := runner().Run(ctx, "", "k3d", "cluster", "create", c.name(),
			"--k3s-arg", "--disable=traefik@server:0",
			"--wait"); err != nil {
			return fmt.Errorf("create cluster %s: %w", c.name(), err)
		}
	}
	return c.InstallDeps(ctx)
}

// Down deletes the cluster and everything in it. This is the only way the
// cluster goes away — verification runs themselves never remove it.
func (c Cluster) Down(ctx context.Context) error {
	found, err := c.exists(ctx)
	if err != nil {
		return err
	}
	if !found {
		c.progress("cluster %s does not exist", c.name())
		return nil
	}
	c.progress("deleting cluster %s", c.name())
	if _, _, err := runner().Run(ctx, "", "k3d", "cluster", "delete", c.name()); err != nil {
		return fmt.Errorf("delete cluster %s: %w", c.name(), err)
	}
	return nil
}

// EnsureUp reports whether the cluster is ready, with a pointer at Up when it
// is not. A verification run never creates the cluster itself: that would put
// the slow path inside the fast one.
func (c Cluster) EnsureUp(ctx context.Context) error {
	found, err := c.exists(ctx)
	if err != nil {
		return err
	}
	if !found {
		return fmt.Errorf("the verification cluster %s does not exist — run `deploy verify up` first", c.name())
	}
	return nil
}

// firstField returns the first space-separated field of a line.
func firstField(line string) string {
	for i, r := range line {
		if r == ' ' || r == '\t' {
			return line[:i]
		}
	}
	return line
}

// splitLines iterates the non-empty lines of a command's output.
func splitLines(b []byte) func(yield func(string) bool) {
	return func(yield func(string) bool) {
		start := 0
		for i, c := range b {
			if c == '\n' {
				if i > start && !yield(string(b[start:i])) {
					return
				}
				start = i + 1
			}
		}
		if len(b) > start {
			yield(string(b[start:]))
		}
	}
}

// notFound classifies a kubectl error as "the object does not exist", which is
// the one answer that is not a failure when ensuring or deleting.
func notFound(err error) bool {
	var ee *command.ExitError
	if !errors.As(err, &ee) {
		return false
	}
	return contains(ee.Stderr, "NotFound") || contains(ee.Stderr, "not found")
}

func contains(s, sub string) bool {
	return len(s) >= len(sub) && (s == sub || len(sub) == 0 || indexOf(s, sub) >= 0)
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

package verify

import (
	"context"
	"fmt"
	"strings"
)

// dependency is one platform piece the overlays under test rely on: a Helm
// release, and optionally the Dapr components a system's host declares, so
// that references resolve to something present.
type dependency struct {
	// name is the Helm release name.
	name string

	// namespace the release installs into, created if absent.
	namespace string

	// repo and chart locate the chart. repo is the repository URL, added
	// under name so `helm repo add` is idempotent.
	repo  string
	chart string

	// version pins the chart. A verification cluster whose dependencies drift
	// would stop being the same target twice, so nothing floats.
	version string

	// set carries --set overrides, rendered inline as k=v.
	set []string

	// daprComponents are applied after the release is ready, in the release's
	// namespace, so the pub/sub and secret store a system's blocks resolve by
	// name exist before any overlay is verified.
	daprComponents []string
}

// dependencies is the fixed platform stack. Fixed rather than configured: the
// point of the cluster is to be one known target, and every repository this
// CLI deploys through runs the same three.
//
// Versions are pins, bumped deliberately. That is the same contract the GitOps
// overlays themselves live under — the target does not move underneath the
// manifest being verified.
var dependencies = []dependency{
	{
		name:      "dapr",
		namespace: "dapr-system",
		repo:      "https://dapr.github.io/helm-charts",
		chart:     "dapr/dapr",
		version:   "1.14.4",
		set:       []string{"global.mtls.enabled=false"},
	},
	{
		name:      "kgateway",
		namespace: "kgateway-system",
		repo:      "oci://ghcr.io/kgateway-dev/charts",
		chart:     "oci://ghcr.io/kgateway-dev/charts/kgateway",
		version:   "v2.0.3",
	},
	{
		name:      "rabbitmq",
		namespace: "rabbitmq",
		repo:      "https://charts.bitnami.com/bitnami",
		chart:     "bitnami/rabbitmq",
		version:   "15.0.6",
		// A verification cluster has one user and no persistence to protect,
		// so the defaults a production chart demands are noise here.
		set: []string{
			"auth.username=intropy",
			"auth.password=intropy",
			"persistence.enabled=false",
		},
		daprComponents: []string{
			rabbitmqPubsubComponent,
			kubernetesSecretStoreComponent,
		},
	},
}

// rabbitmqPubsubComponent is the Dapr pub/sub building block a system host
// declares, pointed at the in-cluster RabbitMQ. The name is the contract: an
// overlay's scopes resolve against it, so it must match what the platform
// templates emit.
const rabbitmqPubsubComponent = `apiVersion: dapr.io/v1alpha1
kind: Component
metadata:
  name: pubsub
  namespace: rabbitmq
spec:
  type: pubsub.rabbitmq
  version: v1
  metadata:
    - name: connectionString
      value: REDACTED
`

// kubernetesSecretStoreComponent is the Dapr secret store a system host
// declares, backed by Kubernetes secrets — the only store a local cluster can
// honour without cloud credentials.
const kubernetesSecretStoreComponent = `apiVersion: dapr.io/v1alpha1
kind: Component
metadata:
  name: secretstore
  namespace: rabbitmq
spec:
  type: secretstores.kubernetes
  version: v1
`

// InstallDeps installs the platform stack, idempotently. Every piece is
// `helm upgrade --install`, so a warm cluster — the common case — costs one
// no-op release each rather than a reinstall.
func (c Cluster) InstallDeps(ctx context.Context) error {
	for _, d := range dependencies {
		if err := c.installDep(ctx, d); err != nil {
			return err
		}
	}
	return nil
}

func (c Cluster) installDep(ctx context.Context, d dependency) error {
	c.progress("ensuring %s (%s@%s)", d.name, d.chart, d.version)

	// OCI charts have no repo to add; the prefix is already the repository.
	if !strings.HasPrefix(d.repo, "oci://") {
		if _, _, err := runner().Run(ctx, "", "helm", "repo", "add", d.name, d.repo); err != nil {
			return fmt.Errorf("helm repo add %s: %w", d.name, err)
		}
	}

	if err := c.kubectl(ctx, "create", "namespace", d.namespace, "--dry-run=client", "-o", "yaml"); err == nil {
		// Namespace exists or was created below; either way the apply owns it.
	}
	out, err := c.renderNamespace(d.namespace)
	if err != nil {
		return err
	}
	if err := c.kubectlStdin(ctx, out, "apply", "-f", "-"); err != nil {
		return fmt.Errorf("ensure namespace %s: %w", d.namespace, err)
	}

	args := []string{
		"upgrade", "--install", d.name, d.chart,
		"--namespace", d.namespace,
		"--version", d.version,
		"--wait",
		"--timeout", "5m",
	}
	for _, s := range d.set {
		args = append(args, "--set", s)
	}
	if _, _, err := runner().Run(ctx, "", "helm", args...); err != nil {
		return fmt.Errorf("install %s: %w", d.name, err)
	}

	for _, comp := range d.daprComponents {
		if err := c.kubectlStdin(ctx, comp, "apply", "-f", "-"); err != nil {
			return fmt.Errorf("apply dapr component for %s: %w", d.name, err)
		}
	}
	return nil
}

// renderNamespace builds a one-document Namespace manifest for apply. Writing
// it through `apply` rather than `create` is what keeps InstallDeps idempotent
// without parsing "already exists" out of an error.
func (c Cluster) renderNamespace(name string) (string, error) {
	return "apiVersion: v1\nkind: Namespace\nmetadata:\n  name: " + name + "\n", nil
}

// kubectl runs kubectl against this cluster's context.
func (c Cluster) kubectl(ctx context.Context, args ...string) error {
	full := append([]string{"--context", KubeContext}, args...)
	if _, _, err := runner().Run(ctx, "", "kubectl", full...); err != nil {
		return err
	}
	return nil
}

// kubectlStdin is kubectl with a manifest piped to stdin. The runner interface
// has no stdin, so the manifest travels as a heredoc through sh — the same
// shape a person types, and the only path that needs no temp file.
func (c Cluster) kubectlStdin(ctx context.Context, manifest string, args ...string) error {
	full := append([]string{"--context", KubeContext}, args...)
	script := "kubectl " + shellJoin(full) + " <<'EOF'\n" + manifest + "\nEOF"
	if _, _, err := runner().Run(ctx, "", "sh", "-c", script); err != nil {
		return err
	}
	return nil
}

// shellJoin quotes arguments for a shell command line. Every argument here is
// generated by this package rather than typed by a user, so single-quoting is
// a safety margin rather than a necessity.
func shellJoin(args []string) string {
	quoted := make([]string, len(args))
	for i, a := range args {
		quoted[i] = "'" + strings.ReplaceAll(a, "'", `'\''`) + "'"
	}
	return strings.Join(quoted, " ")
}

