package verify

import (
	"context"
	"fmt"
	"regexp"
	"strings"
)

// Options configures Run.
type Options struct {
	// Name identifies the run, and becomes the namespace everything is checked
	// against. Lower-cased and sanitised into a legal DNS label.
	Name string

	// Manifests is the rendered overlay, a multi-document YAML stream.
	Manifests []byte

	// Keep retains the run namespace afterwards, for debugging. Deleted on
	// success otherwise; a failed run always keeps it, since that is when the
	// contents matter.
	Keep bool
}

// Result is what a verification run found.
type Result struct {
	// Namespace is where the manifests were checked.
	Namespace string

	// Accepted is the count of resources the API server accepted.
	Accepted int

	// Failures is one entry per resource the dry-run rejected. Empty on
	// success.
	Failures []Failure
}

// Failure is one resource the API server would not admit, with the server's
// own reason. The reason is kubectl's stderr rather than a paraphrase: the
// schema and webhook messages explain themselves better than this package can.
type Failure struct {
	Resource string
	Reason   string
}

// OK reports whether every resource was accepted.
func (r Result) OK() bool { return len(r.Failures) == 0 }

// Run dry-runs manifests against the cluster's API server and reports what
// would be admitted. Nothing is created: this is `kubectl apply
// --dry-run=server`, which runs the full admission chain — CRD schemas,
// webhooks, RBAC — and persists nothing.
//
// That is the phase-one gate. It catches bad CRD references, schema drift,
// broken route bindings and malformed manifests, in seconds, with no image
// pulls and no workloads. What it does not do is run anything: image
// resolution and pod readiness are a later phase, and deliberately out of
// scope here.
func (c Cluster) Run(ctx context.Context, opts Options) (Result, error) {
	if err := c.EnsureUp(ctx); err != nil {
		return Result{}, err
	}
	ns := namespaceName(opts.Name)
	res := Result{Namespace: ns}

	// The namespace is real even though the apply is a dry-run: a server-side
	// dry-run still evaluates namespaced admission against the actual
	// namespace, so it has to exist.
	if err := c.kubectlStdin(ctx, renderNamespace(ns), "apply", "-f", "-"); err != nil {
		return res, fmt.Errorf("create namespace %s: %w", ns, err)
	}

	// A failed run keeps its namespace: that is the case someone debugs.
	// A kept run keeps it too. Only success-without-keep cleans up, and the
	// deletion is deferred so it happens however the run ends.
	tornDown := false
	defer func() {
		if opts.Keep || !res.OK() || tornDown {
			return
		}
		// Teardown is best-effort: the verification result is already decided,
		// and a leaked namespace is untidy rather than wrong.
		_ = c.kubectl(context.Background(), "delete", "namespace", ns, "--wait=false")
	}()

	failures, accepted, err := c.dryRun(ctx, ns, opts.Manifests)
	if err != nil {
		return res, err
	}
	res.Accepted = accepted
	res.Failures = failures
	tornDown = false
	return res, nil
}

// Teardown deletes a run's namespace. Exported for the failure path a caller
// wants to clean up explicitly after inspecting it.
func (c Cluster) Teardown(ctx context.Context, name string) error {
	ns := namespaceName(name)
	if err := c.kubectl(ctx, "delete", "namespace", ns, "--wait=false"); err != nil {
		return fmt.Errorf("delete namespace %s: %w", ns, err)
	}
	return nil
}

// dryRun applies manifests server-side with --dry-run=server and reads which
// resources were admitted and which were not. kubectl exits non-zero when any
// document is rejected, with the rejections on stderr; both halves of that
// answer are the report.
func (c Cluster) dryRun(ctx context.Context, ns string, manifests []byte) (failures []Failure, accepted int, err error) {
	stdout, stderr, runErr := runner().Run(ctx, "", "sh", "-c",
		"kubectl --context "+KubeContext+" apply --dry-run=server --server-side -n "+ns+" -f - <<'EOF'\n"+string(manifests)+"\nEOF")

	accepted = countLines(stdout, "(server dry run)")
	if runErr == nil {
		return nil, accepted, nil
	}

	// A rejection names the resource on one line and the reason after. The
	// resource is the "The <kind> \"<name>\" is invalid" prefix kubectl prints;
	// anything before it on stderr is warning noise from the API server.
	rejects := parseRejections(stderr.String())
	if len(rejects) == 0 {
		// kubectl failed without a per-resource rejection — the cluster
		// unreachable, the manifest unparsable. That is an error in the run,
		// not a verdict on a resource.
		return nil, accepted, fmt.Errorf("dry-run against %s: %w", ns, runErr)
	}
	return rejects, accepted, nil
}

// rejectionRe matches kubectl's per-resource failure line: `The Deployment
// "order-extractor" is invalid: spec.template...`.
var rejectionRe = regexp.MustCompile(`^The ([A-Za-z0-9.\-]+) "([^"]+)" is invalid: (.+)$`)

func parseRejections(stderr string) []Failure {
	var out []Failure
	var cur *Failure
	for _, line := range strings.Split(stderr, "\n") {
		line = strings.TrimRight(line, "\r")
		if m := rejectionRe.FindStringSubmatch(line); m != nil {
			out = append(out, Failure{Resource: m[1] + " " + m[2], Reason: m[3]})
			cur = &out[len(out)-1]
			continue
		}
		// Continuation lines of a multi-line reason belong to the open failure.
		if cur != nil && strings.HasPrefix(line, " ") {
			cur.Reason += "\n" + strings.TrimSpace(line)
		}
	}
	return out
}

// countLines counts output lines containing a marker, e.g. `deployment.apps/x
// configured (server dry run)`.
func countLines(b []byte, marker string) int {
	n := 0
	for line := range splitLines(b) {
		if strings.Contains(line, marker) {
			n++
		}
	}
	return n
}

// invalidNameChars is everything a DNS label may not carry.
var invalidNameChars = regexp.MustCompile(`[^a-z0-9\-]+`)

// namespaceName renders a run name into a legal namespace: lower-case, DNS
// characters only, prefixed so a bare `kubectl get ns` shows what made it.
func namespaceName(name string) string {
	n := strings.ToLower(name)
	n = invalidNameChars.ReplaceAllString(n, "-")
	n = strings.Trim(n, "-")
	if n == "" {
		n = "run"
	}
	// A label is 63 characters; the prefix leaves room for the longest run
	// name a component coordinate produces.
	if len(n) > 50 {
		n = n[:50]
		n = strings.TrimRight(n, "-")
	}
	return "verify-" + n
}

