// VerifyOptions configures VerifyCmd.
//
// There is no Version, no SourceDir and no PlanOnly: a verification reads no
// source repository and resolves no digests — it renders the overlay as it
// stands and asks the cluster whether the manifests would be admitted.
// Environment is optional rather than required, unlike every sibling: the
// verify environment is discovered from deploy.yaml, and --env only narrows it
// when several are defined.
type VerifyOptions struct {
	Component string
	Domain    string
	System    string

	// Environment names the verify environment. Empty means the single one
	// deploy.yaml defines.
	Environment string

	// Keep retains the run namespace afterwards, for debugging.
	Keep bool

	GitopsRepo   string
	OutputFormat string
	CacheRoot    string

	Runner    command.Runner
	UserAgent string
	Stdout    io.Writer
	Stderr    io.Writer
}

func (o VerifyOptions) output() output {
	return output{Format: o.OutputFormat, Stdout: o.Stdout, Stderr: o.Stderr}
}

func (o VerifyOptions) session() sessionOptions {
	return sessionOptions{
		GitopsRepo: o.GitopsRepo,
		CacheRoot:  o.CacheRoot,
		Runner:     o.Runner,
		Stderr:     o.Stderr,
	}
}

func (o *VerifyOptions) applyDefaults() {
	if o.Runner == nil {
		o.Runner = git.DefaultRunner()
	}
	if o.OutputFormat == "" {
		o.OutputFormat = OutputPlain
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
}

// VerifyClusterOptions configures VerifyUp and VerifyDown. There is no
// GitopsRepo: the cluster is a local fixture, not a repository concern.
type VerifyClusterOptions struct {
	Runner command.Runner
	Stdout io.Writer
	Stderr io.Writer
}

func (o *VerifyClusterOptions) applyDefaults() {
	if o.Runner == nil {
		o.Runner = git.DefaultRunner()
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
}

// requireBinaries is the package-local shorthand for command.RequireBinaries.
func requireBinaries(names ...string) error {
	return command.RequireBinaries(names...)
}

