package deploy

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
	"github.com/integrio-intropy/intropy-cli/internal/verify"
)

// VerifyCmd dry-runs a component's verify-environment overlay against the
// local verification cluster. Nothing is created: the apply is a server-side
// dry-run, which exercises the API server's admission chain — CRD schemas,
// webhooks — without persisting a thing. The digests and the runtime are the
// other commands' business; this one answers only "would the manifests be
// admitted".
func VerifyCmd(ctx context.Context, opts VerifyOptions) error {
	opts.applyDefaults()
	out := opts.output()

	// git reads the checkout; kustomize renders; k3d/kubectl/helm are the
	// cluster. Demanding all of them up front is what stops a missing helm
	// surfacing only after the render.
	binaries := append([]string{"git", "kustomize"}, verify.Binaries...)
	s, err := openSession(ctx, opts.session(), binaries...)
	if err != nil {
		return err
	}
	defer s.Close()
	repo, deployCfg := s.repo, s.deployCfg

	envName, _, err := verifyEnvironment(deployCfg, opts.Environment)
	if err != nil {
		return err
	}

	coord, comp, err := s.locateComponent(opts.Component, opts.Domain, opts.System)
	if err != nil {
		return err
	}
	overlayDir, err := gitops.ResolveOverlay(repo.Root, coord, comp, envName)
	if err != nil {
		return err
	}

	cluster := verify.Cluster{Stderr: opts.Stderr}
	if err := cluster.EnsureUp(ctx); err != nil {
		return err
	}

	// Rendered locally rather than through ArgoCD: there is no ArgoCD here.
	// That trades away the render-fidelity guarantee diff.go insists on, and
	// the trade is honest — a verify overlay is one this repository controls
	// entirely, so the Application-level overrides a local build misses do not
	// exist for it.
	manifests, err := kustomize.Client{Runner: opts.Runner}.Build(ctx, overlayDir)
	if err != nil {
		return err
	}

	res, err := cluster.Run(ctx, verify.Options{
		Name:      coord.String(),
		Manifests: manifests,
		Keep:      opts.Keep,
	})
	if err != nil {
		return err
	}
	return reportVerify(out, coord, envName, res)
}

// VerifyUp brings up the verification cluster and its platform dependencies.
// Idempotent: on a warm cluster it is a cheap no-op, which is the whole point
// of keeping the cluster around.
func VerifyUp(ctx context.Context, opts VerifyClusterOptions) error {
	opts.applyDefaults()
	if err := command.RequireBinaries(verify.Binaries...); err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "bringing up the verification cluster\n")
	return verify.Cluster{Stderr: opts.Stderr}.Up(ctx)
}

// VerifyDown deletes the verification cluster and everything in it.
func VerifyDown(ctx context.Context, opts VerifyClusterOptions) error {
	opts.applyDefaults()
	if err := command.RequireBinaries(verify.Binaries...); err != nil {
		return err
	}
	return verify.Cluster{Stderr: opts.Stderr}.Down(ctx)
}

// verifyEnvironment resolves which environment is the verify one, honouring an
// explicit --env and defaulting to the single one deploy.yaml defines.
func verifyEnvironment(cfg *gitops.DeployConfig, requested string) (string, gitops.EnvironmentConfig, error) {
	if requested != "" {
		env, err := cfg.Environment(requested)
		if err != nil {
			return "", gitops.EnvironmentConfig{}, err
		}
		if !env.Verify {
			return "", gitops.EnvironmentConfig{}, fmt.Errorf("%s is not a verify environment; `deploy verify` only dry-runs the local verification one", requested)
		}
		return requested, env, nil
	}
	names := cfg.VerifyEnvironments()
	switch len(names) {
	case 0:
		return "", gitops.EnvironmentConfig{}, fmt.Errorf("%s defines no verify environment — mark one with `verify: true` to use `deploy verify`", gitops.DeployFileName)
	case 1:
		env, _ := cfg.Environment(names[0])
		return names[0], env, nil
	default:
		return "", gitops.EnvironmentConfig{}, fmt.Errorf("%s defines several verify environments (%s); pass --env to choose", gitops.DeployFileName, strings.Join(names, ", "))
	}
}

// reportVerify writes the result. The exit code carries the verdict: any
// rejection is a failure even though the command ran cleanly, so JSON and
// plain both end non-zero on a rejected resource.
func reportVerify(out output, coord gitops.Coordinate, env string, res verify.Result) error {
	if out.Format == OutputJSON {
		payload := map[string]any{
			"component":   coord.String(),
			"environment": env,
			"namespace":   res.Namespace,
			"accepted":    res.Accepted,
			"verified":    res.OK(),
		}
		if !res.OK() {
			failures := make([]map[string]string, 0, len(res.Failures))
			for _, f := range res.Failures {
				failures = append(failures, map[string]string{"resource": f.Resource, "reason": f.Reason})
			}
			payload["failures"] = failures
		}
		enc := json.NewEncoder(out.Stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(payload); err != nil {
			return err
		}
	} else {
		if res.OK() {
			fmt.Fprintf(out.Stdout, "%s: verified against %s — %d resources admitted (%s, server dry-run)\n",
				coord, env, res.Accepted, res.Namespace)
		} else {
			fmt.Fprintf(out.Stdout, "%s: %d of %d resources rejected against %s (%s):\n",
				coord, len(res.Failures), res.Accepted+len(res.Failures), env, res.Namespace)
			for _, f := range res.Failures {
				fmt.Fprintf(out.Stdout, "  %s: %s\n", f.Resource, f.Reason)
			}
		}
	}
	if !res.OK() {
		return &VerificationFailedError{Component: coord.String(), Failures: len(res.Failures)}
	}
	return nil
}

// VerificationFailedError reports that the run completed and found resources
// the cluster would reject. Distinct from a command error — the verification
// worked; the manifests did not — so main maps it to its own exit code.
type VerificationFailedError struct {
	Component string
	Failures  int
}

func (e *VerificationFailedError) Error() string {
	return fmt.Sprintf("%s: %d resource(s) would be rejected by the verification cluster", e.Component, e.Failures)
}

