package verify

import (
	"context"
	"errors"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/command"
)

// fakeRunner scripts command responses keyed on a substring of the joined
// command line, and records what ran. The cluster calls here are shell-shaped
// (k3d, kubectl, a heredoc through sh), so a substring match is the honest
// seam — matching the whole line would couple the test to quoting.
type fakeRunner struct {
	calls   []string
	results map[string]fakeResult
	def     fakeResult
}

type fakeResult struct {
	stdout string
	stderr string
	err    error
}

func (f *fakeRunner) Run(_ context.Context, _, name string, args ...string) ([]byte, []byte, error) {
	key := name + " " + strings.Join(args, " ")
	f.calls = append(f.calls, key)
	for substr, res := range f.results {
		if strings.Contains(key, substr) {
			return []byte(res.stdout), []byte(res.stderr), res.err
		}
	}
	return []byte(f.def.stdout), []byte(f.def.stderr), f.def.err
}

func (f *fakeRunner) called(substr string) bool {
	for _, c := range f.calls {
		if strings.Contains(c, substr) {
			return true
		}
	}
	return false
}

func stubRunner(t *testing.T, r *fakeRunner) {
	t.Helper()
	original := Runner
	Runner = r
	t.Cleanup(func() { Runner = original })
}

func TestNamespaceName(t *testing.T) {
	cases := map[string]string{
		"orders/order-flow/order-extractor": "verify-orders-order-flow-order-extractor",
		"Order_Extractor":                   "verify-order-extractor",
		"---":                               "verify-run",
		"":                                  "verify-run",
	}
	for in, want := range cases {
		if got := namespaceName(in); got != want {
			t.Errorf("namespaceName(%q) = %q, want %q", in, got, want)
		}
	}
	// The prefix plus a long name must still be a legal 63-character label.
	if got := namespaceName(strings.Repeat("a", 100)); len(got) > 63 {
		t.Errorf("namespaceName(long) = %d chars, want <= 63", len(got))
	}
}

func TestParseRejections(t *testing.T) {
	stderr := `Warning: something from the apiserver
The Deployment "order-extractor" is invalid: spec.template.spec.containers[0].image: Required value
The HTTPRoute "orders" is invalid: spec.parentRefs[0].name: Not found: "gateway"
`
	failures := parseRejections(stderr)
	if len(failures) != 2 {
		t.Fatalf("parseRejections found %d, want 2: %+v", len(failures), failures)
	}
	if failures[0].Resource != `Deployment order-extractor` {
		t.Errorf("failures[0].Resource = %q", failures[0].Resource)
	}
	if !strings.Contains(failures[0].Reason, "Required value") {
		t.Errorf("failures[0].Reason = %q", failures[0].Reason)
	}
	if failures[1].Resource != `HTTPRoute orders` {
		t.Errorf("failures[1].Resource = %q", failures[1].Resource)
	}
}

func TestParseRejectionsNone(t *testing.T) {
	if got := parseRejections("Error from server: connection refused\n"); len(got) != 0 {
		t.Errorf("parseRejections(connection error) = %v, want none — that is a run error, not a verdict", got)
	}
}

func TestClusterExists(t *testing.T) {
	r := &fakeRunner{results: map[string]fakeResult{
		"cluster list": {stdout: "intropy-verify   1/2 running\nother            1/1 running\n"},
	}}
	stubRunner(t, r)

	found, err := Cluster{}.exists(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if !found {
		t.Error("exists should find intropy-verify in the list")
	}
}

func TestClusterExistsAbsent(t *testing.T) {
	r := &fakeRunner{results: map[string]fakeResult{
		"cluster list": {stdout: "other   1/1 running\n"},
	}}
	stubRunner(t, r)

	found, err := Cluster{}.exists(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if found {
		t.Error("exists should not find intropy-verify")
	}
}

// Up on a warm cluster must not recreate it: the whole speed story is that an
// existing cluster is a no-op.
func TestUpSkipsCreatingAnExistingCluster(t *testing.T) {
	r := &fakeRunner{results: map[string]fakeResult{
		"cluster list": {stdout: "intropy-verify   1/2 running\n"},
	}}
	stubRunner(t, r)

	if err := (Cluster{}).Up(context.Background()); err != nil {
		t.Fatal(err)
	}
	if r.called("cluster create") {
		t.Error("Up created a cluster that already exists")
	}
	// Dependencies are still ensured — that half is meant to be idempotent
	// rather than skipped.
	if !r.called("upgrade --install dapr") {
		t.Error("Up should still ensure the dapr release")
	}
	if !r.called("upgrade --install kgateway") {
		t.Error("Up should ensure the kgateway release")
	}
	if !r.called("upgrade --install rabbitmq") {
		t.Error("Up should ensure the rabbitmq release")
	}
}

func TestUpCreatesAMissingCluster(t *testing.T) {
	r := &fakeRunner{results: map[string]fakeResult{
		"cluster list": {stdout: ""},
	}}
	stubRunner(t, r)

	if err := (Cluster{}).Up(context.Background()); err != nil {
		t.Fatal(err)
	}
	if !r.called("cluster create intropy-verify") {
		t.Errorf("Up should create the cluster, calls: %v", r.calls)
	}
	if !r.called("--disable=traefik") {
		t.Error("the cluster should not bring up traefik — kgateway is the ingress")
	}
}

// A run against a missing cluster points at up rather than failing obscurely
// in kubectl.
func TestRunRequiresTheCluster(t *testing.T) {
	r := &fakeRunner{results: map[string]fakeResult{
		"cluster list": {stdout: ""},
	}}
	stubRunner(t, r)

	_, err := (Cluster{}).Run(context.Background(), Options{Name: "c", Manifests: []byte("x")})
	if err == nil {
		t.Fatal("expected an error")
	}
	if !strings.Contains(err.Error(), "deploy verify up") {
		t.Errorf("error %q should point at `deploy verify up`", err)
	}
}

func TestDryRunAccepted(t *testing.T) {
	r := &fakeRunner{results: map[string]fakeResult{
		"cluster list": {stdout: "intropy-verify   1/1 running\n"},
		"dry-run=server": {stdout: "deployment.apps/order-extractor configured (server dry run)\nservice/order-extractor configured (server dry run)\n"},
	}}
	stubRunner(t, r)

	res, err := (Cluster{}).Run(context.Background(), Options{Name: "c", Manifests: []byte("x")})
	if err != nil {
		t.Fatal(err)
	}
	if !res.OK() {
		t.Errorf("result should be OK: %+v", res.Failures)
	}
	if res.Accepted != 2 {
		t.Errorf("Accepted = %d, want 2", res.Accepted)
	}
	// Success without --keep tears the namespace down.
	if !r.called("delete namespace") {
		t.Error("a successful run should delete its namespace")
	}
}

func TestDryRunRejected(t *testing.T) {
	r := &fakeRunner{results: map[string]fakeResult{
		"cluster list": {stdout: "intropy-verify   1/1 running\n"},
		"dry-run=server": {
			stdout: "deployment.apps/order-extractor configured (server dry run)\n",
			stderr: "The HTTPRoute \"orders\" is invalid: spec.parentRefs[0].name: Not found\n",
			err:    errors.New("exit status 1"),
		},
	}}
	stubRunner(t, r)

	res, err := (Cluster{}).Run(context.Background(), Options{Name: "c", Manifests: []byte("x")})
	if err != nil {
		t.Fatal(err)
	}
	if res.OK() {
		t.Fatal("result should not be OK")
	}
	if len(res.Failures) != 1 || res.Failures[0].Resource != "HTTPRoute orders" {
		t.Errorf("Failures = %+v", res.Failures)
	}
	// A failed run keeps its namespace for debugging, even without --keep.
	if r.called("delete namespace") {
		t.Error("a failed run must keep its namespace")
	}
}

// A cluster that cannot be reached is an error in the run, not a verdict on
// the manifests.
func TestDryRunUnreachableIsAnError(t *testing.T) {
	r := &fakeRunner{results: map[string]fakeResult{
		"cluster list": {stdout: "intropy-verify   1/1 running\n"},
		"dry-run=server": {
			stderr: "The connection to the server localhost:8080 was refused\n",
			err:    errors.New("exit status 1"),
		},
	}}
	stubRunner(t, r)

	_, err := (Cluster{}).Run(context.Background(), Options{Name: "c", Manifests: []byte("x")})
	if err == nil {
		t.Fatal("an unreachable cluster must be an error, not a rejection list")
	}
}

func TestKeepRetainsTheNamespace(t *testing.T) {
	r := &fakeRunner{results: map[string]fakeResult{
		"cluster list": {stdout: "intropy-verify   1/1 running\n"},
		"dry-run=server": {stdout: "deployment.apps/x configured (server dry run)\n"},
	}}
	stubRunner(t, r)

	if _, err := (Cluster{}).Run(context.Background(), Options{Name: "c", Manifests: []byte("x"), Keep: true}); err != nil {
		t.Fatal(err)
	}
	if r.called("delete namespace") {
		t.Error("--keep must retain the namespace")
	}
}

