package deploy

import (
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/gitops"
)

func deployCfgWith(envs map[string]gitops.EnvironmentConfig) *gitops.DeployConfig {
	return &gitops.DeployConfig{SchemaVersion: 1, Registry: "r", Environments: envs}
}

func TestVerifyEnvironmentDefaultsToTheOnlyOne(t *testing.T) {
	cfg := deployCfgWith(map[string]gitops.EnvironmentConfig{
		"dev":    {Sync: gitops.SyncAuto},
		"verify": {Sync: gitops.SyncAuto, Verify: true},
	})
	name, _, err := verifyEnvironment(cfg, "")
	if err != nil {
		t.Fatal(err)
	}
	if name != "verify" {
		t.Errorf("name = %q, want verify", name)
	}
}

func TestVerifyEnvironmentRequiresAVerifyEnvironment(t *testing.T) {
	cfg := deployCfgWith(map[string]gitops.EnvironmentConfig{
		"dev": {Sync: gitops.SyncAuto},
	})
	_, _, err := verifyEnvironment(cfg, "")
	if err == nil {
		t.Fatal("expected an error when no verify environment is defined")
	}
	if !strings.Contains(err.Error(), "verify: true") {
		t.Errorf("error %q should say how to define one", err)
	}
}

// A named environment that is not the verify one is refused: the command only
// ever dry-runs the local verification environment.
func TestVerifyEnvironmentRefusesANonVerifyName(t *testing.T) {
	cfg := deployCfgWith(map[string]gitops.EnvironmentConfig{
		"dev":    {Sync: gitops.SyncAuto},
		"verify": {Sync: gitops.SyncAuto, Verify: true},
	})
	_, _, err := verifyEnvironment(cfg, "dev")
	if err == nil {
		t.Fatal("expected an error naming a non-verify environment")
	}
	if !strings.Contains(err.Error(), "not a verify environment") {
		t.Errorf("error %q should say dev is not a verify environment", err)
	}
}

func TestVerifyEnvironmentHonoursAnExplicitName(t *testing.T) {
	cfg := deployCfgWith(map[string]gitops.EnvironmentConfig{
		"verify": {Sync: gitops.SyncAuto, Verify: true},
	})
	name, _, err := verifyEnvironment(cfg, "verify")
	if err != nil {
		t.Fatal(err)
	}
	if name != "verify" {
		t.Errorf("name = %q, want verify", name)
	}
}

// Several verify environments are legal in the file; the command just cannot
// guess between them.
func TestVerifyEnvironmentAmbiguousWithoutAName(t *testing.T) {
	cfg := deployCfgWith(map[string]gitops.EnvironmentConfig{
		"verify-a": {Sync: gitops.SyncAuto, Verify: true},
		"verify-b": {Sync: gitops.SyncAuto, Verify: true},
	})
	_, _, err := verifyEnvironment(cfg, "")
	if err == nil {
		t.Fatal("expected an ambiguity error")
	}
	if !strings.Contains(err.Error(), "--env") {
		t.Errorf("error %q should point at --env", err)
	}
}

// deploy, diff and sync all assume an ArgoCD-reconciled environment, so a
// verify environment is a category error for each of them.
func TestRequireNotVerify(t *testing.T) {
	verifyEnv := gitops.EnvironmentConfig{Sync: gitops.SyncAuto, Verify: true}
	for _, command := range []string{"deploy", "diff", "sync"} {
		err := requireNotVerify(command, "verify", verifyEnv)
		if err == nil {
			t.Errorf("%s: expected an error", command)
			continue
		}
		if !strings.Contains(err.Error(), "verify environment") || !strings.Contains(err.Error(), "deploy verify") {
			t.Errorf("%s: error %q should name the environment and the right command", command, err)
		}
	}
	// A plain environment is never refused.
	if err := requireNotVerify("deploy", "dev", gitops.EnvironmentConfig{Sync: gitops.SyncAuto}); err != nil {
		t.Errorf("a non-verify environment must not be refused: %v", err)
	}
}

package main

import (
	"bytes"
	"strings"
	"testing"
)

func resetVerifyState(t *testing.T, stdout, stderr *bytes.Buffer) {
	t.Helper()
	resetRootIO(t, stdout, stderr)
	verifyFlagValues = verifyFlags{output: "plain"}
	t.Cleanup(func() { verifyFlagValues = verifyFlags{output: "plain"} })
}

func runVerify(t *testing.T, args ...string) (stdout, stderr *bytes.Buffer, err error) {
	t.Helper()
	stdout, stderr = &bytes.Buffer{}, &bytes.Buffer{}
	resetVerifyState(t, stdout, stderr)
	rootCmd.SetArgs(append([]string{"deploy", "verify"}, args...))
	return stdout, stderr, rootCmd.Execute()
}

func TestVerifyRequiresComponent(t *testing.T) {
	_, _, err := runVerify(t)
	if err == nil {
		t.Fatal("expected an error when no component is given")
	}
	if code := exitCode(err); code != 2 {
		t.Errorf("exit code = %d, want 2 for a usage error", code)
	}
}

// A bare --env is not required for verify, unlike every sibling: the
// environment is discovered. What is required is that a *named* environment is
// not a non-verify one — that is the command's own guard, exercised in the
// deploy package.
func TestVerifyDoesNotRequireEnv(t *testing.T) {
	// Parsing must not fail on the missing --env; the command fails later (no
	// gitops repo configured in the test), which is beyond the usage layer.
	_, _, err := runVerify(t, "order-extractor", "--definitely-not-a-flag")
	if err == nil {
		t.Fatal("an unknown flag is a usage error")
	}
	if code := exitCode(err); code != 2 {
		t.Errorf("exit code = %d, want 2", code)
	}
	if !strings.Contains(err.Error(), "unknown flag") {
		t.Errorf("error %q should be the unknown flag", err)
	}
}

func TestVerifyRejectsBadOutput(t *testing.T) {
	_, _, err := runVerify(t, "order-extractor", "-o", "yaml")
	if err == nil {
		t.Fatal("expected an error for an unsupported output format")
	}
	if code := exitCode(err); code != 2 {
		t.Errorf("exit code = %d, want 2", code)
	}
}

func TestVerifyUpTakesNoArgs(t *testing.T) {
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	resetRootIO(t, stdout, stderr)
	rootCmd.SetArgs([]string{"deploy", "verify", "up", "extra"})
	err := rootCmd.Execute()
	if err == nil {
		t.Fatal("up takes no arguments")
	}
	if code := exitCode(err); code != 2 {
		t.Errorf("exit code = %d, want 2", code)
	}
}

func TestVerifyDownTakesNoArgs(t *testing.T) {
	stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
	resetRootIO(t, stdout, stderr)
	rootCmd.SetArgs([]string{"deploy", "verify", "down", "extra"})
	err := rootCmd.Execute()
	if err == nil {
		t.Fatal("down takes no arguments")
	}
	if code := exitCode(err); code != 2 {
		t.Errorf("exit code = %d, want 2", code)
	}
}

