content.text:
package verify

import (
	"context"
	"fmt"
	"strings"
)

// dependency is one platform piece the overlays under test rely on: a Helm
// release, and optionally the Dapr components a system's host declares, so
// that references resolve to something present.
type dependency struct {
	// name is the Helm release name.
	name string

	// namespace the release installs into, created if absent.
	namespace string

	// repo and chart locate the chart. repo is the repository URL, added under
	// repoName so `helm repo add` is idempotent. chart is the chart reference
	// handed to `upgrade --install`: <repoName>/<chart> for an index repo, the
	// full OCI URL for an OCI one.
	repo     string
	repoName string
	chart    string

	// version pins the chart. A verification cluster whose dependencies drift
	// would stop being the same target twice, so nothing floats.
	version string

	// set carries --set overrides, rendered inline as k=v.
	set []string

	// daprComponents are applied after the release is ready, in the release's
	// namespace, so the pub/sub and secret store a system's blocks resolve by
	// name exist before any overlay is verified.
	daprComponents []string
}

// dependencies is the fixed platform stack. Fixed rather than configured: the
// point of the cluster is to be one known target, and every repository this
// CLI deploys through runs the same three.
//
// Versions are pins, bumped deliberately. That is the same contract the GitOps
// overlays themselves live under — the target does not move underneath the
// manifest being verified.
var dependencies = []dependency{
	{
		name:      "dapr",
		namespace: "dapr-system",
		repo:      "https://dapr.github.io/helm-charts",
		repoName: "dapr",
		chart:    "dapr/dapr",
		version:  "1.14.4",
		set:      []string{"global.mtls.enabled=false"},
	},
	{
		name:      "kgateway",
		namespace: "kgateway-system",
		repo:      "oci://ghcr.io/kgateway-dev/charts",
		chart:     "oci://ghcr.io/kgateway-dev/charts/kgateway",
		version:   "v2.0.3",
	},
	{
		name:      "rabbitmq",
		namespace: "rabbitmq",
		repo:      "https://charts.bitnami.com/bitnami",
		// Not "bitnami": that name is usually already taken by the user's own
		// registration, and a no-op `repo add` then leaves helm looking for a
		// bitnami-index.yaml that was never fetched. A distinct entry is added
		// and indexed for real.
		repoName: "intropy-bitnami",
		chart:    "intropy-bitnami/rabbitmq",
		version:  "15.0.6",
		// A verification cluster has one user and no persistence to protect,
		// so the defaults a production chart demands are noise here.
		set: []string{
			"auth.username=intropy",
			"auth.password=intropy",
			"persistence.enabled=false",
		},
		daprComponents: []string{
			rabbitmqPubsubComponent,
			kubernetesSecretStoreComponent,
		},
	},
}

// rabbitmqPubsubComponent is the Dapr pub/sub building block a system host
// declares, pointed at the in-cluster RabbitMQ. The name is the contract: an
// overlay's scopes resolve against it, so it must match what the platform
// templates emit.
const rabbitmqPubsubComponent = `apiVersion: dapr.io/v1alpha1
kind: Component
metadata:
  name: pubsub
  namespace: rabbitmq
spec:
  type: pubsub.rabbitmq
  version: v1
  metadata:
    - name: connectionString
      value: REDACTED
`

// kubernetesSecretStoreComponent is the Dapr secret store a system host
// declares, backed by Kubernetes secrets — the only store a local cluster can
// honour without cloud credentials.
const kubernetesSecretStoreComponent = `apiVersion: dapr.io/v1alpha1
kind: Component
metadata:
  name: secretstore
  namespace: rabbitmq
spec:
  type: secretstores.kubernetes
  version: v1
`

// InstallDeps installs the platform stack, idempotently. Every piece is
// `helm upgrade --install`, so a warm cluster — the common case — costs one
// no-op release each rather than a reinstall.
func (c Cluster) InstallDeps(ctx context.Context) error {
	for _, d := range dependencies {
		if err := c.installDep(ctx, d); err != nil {
			return err
		}
	}
	return nil
}

func (c Cluster) installDep(ctx context.Context, d dependency) error {
	c.progress("ensuring %s (%s@%s)", d.name, d.chart, d.version)

	// OCI charts have no repo to add; the prefix is already the repository.
	// For the rest, `repo add` records the URL and fetches the index — the
	// file `upgrade --install <repo>/<chart>` actually reads. Skip the add and
	// the install fails with "no cached repo found" on a fresh machine.
	if !strings.HasPrefix(d.repo, "oci://") {
		if _, _, err := runner().Run(ctx, "", "helm", "repo", "add", d.repoName, d.repo); err != nil {
			return fmt.Errorf("helm repo add %s: %w", d.repoName, err)
		}
		if _, _, err := runner().Run(ctx, "", "helm", "repo", "update", d.repoName); err != nil {
			return fmt.Errorf("helm repo update %s: %w", d.repoName, err)
		}
	}

	if err := c.kubectlStdin(ctx, renderNamespace(d.namespace), "apply", "-f", "-"); err != nil {
		return fmt.Errorf("ensure namespace %s: %w", d.namespace, err)
	}

	args := []string{
		"upgrade", "--install", d.name, d.chart,
		"--namespace", d.namespace,
		"--version", d.version,
		"--wait",
		"--timeout", "5m",
	}
	for _, s := range d.set {
		args = append(args, "--set", s)
	}
	if _, _, err := runner().Run(ctx, "", "helm", args...); err != nil {
		return fmt.Errorf("install %s: %w", d.name, err)
	}

	for _, comp := range d.daprComponents {
		if err := c.kubectlStdin(ctx, comp, "apply", "-f", "-"); err != nil {
			return fmt.Errorf("apply dapr component for %s: %w", d.name, err)
		}
	}
	return nil
}

// renderNamespace builds a one-document Namespace manifest for apply. Writing
// it through `apply` rather than `create` is what keeps InstallDeps idempotent
// without parsing "already exists" out of an error.
func renderNamespace(name string) string {
	return "apiVersion: v1\nkind: Namespace\nmetadata:\n  name: " + name + "\n"
}

// kubectl runs kubectl against this cluster's context.
func (c Cluster) kubectl(ctx context.Context, args ...string) error {
	full := append([]string{"--context", KubeContext}, args...)
	if _, _, err := runner().Run(ctx, "", "kubectl", full...); err != nil {
		return err
	}
	return nil
}

// kubectlStdin is kubectl with a manifest piped to stdin. The runner interface
// has no stdin, so the manifest travels as a heredoc through sh — the same
// shape a person types, and the only path that needs no temp file.
func (c Cluster) kubectlStdin(ctx context.Context, manifest string, args ...string) error {
	full := append([]string{"--context", KubeContext}, args...)
	script := "kubectl " + shellJoin(full) + " <<'EOF'\n" + manifest + "\nEOF"
	if _, _, err := runner().Run(ctx, "", "sh", "-c", script); err != nil {
		return err
	}
	return nil
}

// shellJoin quotes arguments for a shell command line. Every argument here is
// generated by this package rather than typed by a user, so single-quoting is
// a safety margin rather than a necessity.
func shellJoin(args []string) string {
	quoted := make([]string, len(args))
	for i, a := range args {
		quoted[i] = "'" + strings.ReplaceAll(a, "'", `'\''`) + "'"
	}
	return strings.Join(quoted, " ")
}

