// kubectlStdin is kubectl with a manifest piped to stdin. The runner interface
// has no stdin, so the manifest goes through printf — a single-quoted string
// with its own quotes escaped. A heredoc would do, but a multi-document stream
// confuses the interactive EOF marker, and every manifest here is generated by
// this package, so quoting is a safety margin rather than a necessity.
func (c Cluster) kubectlStdin(ctx context.Context, manifest string, args ...string) error {
	full := append([]string{"--context", KubeContext}, args...)
	script := "printf '%s' " + shellQuote(manifest) + " | kubectl " + shellJoin(full)
	if _, _, err := runner().Run(ctx, "", "sh", "-c", script); err != nil {
		return err
	}
	return nil
}

// shellQuote renders a string as a single-quoted shell word.
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

// shellJoin quotes arguments for a shell command line.
func shellJoin(args []string) string {
	quoted := make([]string, len(args))
	for i, a := range args {
		quoted[i] = shellQuote(a)
	}
	return strings.Join(quoted, " ")
}

